import tiers from "../character/modelTiers.generated.json";

/**
 * Player model detail. Five tiers are generated by
 * `scripts/character/generate_character.py --lod <tier>` with the same parts
 * and pivots, so any of them can drive the same rig and be swapped at runtime.
 *
 * The automatic choice combines what can be known about the device:
 *   1. the GPU class, from the WebGL renderer string (a heuristic: browsers
 *      may mask or simplify it, in which case it is "unknown");
 *   2. the connection class, which only limits how much is downloaded
 *      (it affects loading time, not the frame rate once loaded).
 * Anything unknown falls back to a conservative choice: medium on desktop,
 * low on touch devices. "super" is never picked automatically.
 */
export const MODEL_TIERS = [
  "very-low",
  "low",
  "medium",
  "high",
  "super",
] as const;
export type ModelTier = (typeof MODEL_TIERS)[number];
export type ModelChoice = ModelTier | "auto";

export function isModelTier(value: unknown): value is ModelTier {
  return (
    typeof value === "string" &&
    (MODEL_TIERS as readonly string[]).includes(value)
  );
}

export function isModelChoice(value: unknown): value is ModelChoice {
  return value === "auto" || isModelTier(value);
}

interface TierInfo {
  file: string;
  triangles: number;
  bytes: number;
}

const TIER_INFO = tiers as Partial<Record<ModelTier, TierInfo>>;

/** Tiers whose model file exists (from the generator's manifest). */
export const AVAILABLE_TIERS: readonly ModelTier[] = MODEL_TIERS.filter(
  (tier) => TIER_INFO[tier],
);

export function tierInfo(tier: ModelTier): TierInfo | undefined {
  return TIER_INFO[tier];
}

export function modelUrl(tier: ModelTier): string {
  return `/models/${TIER_INFO[tier]?.file ?? "hacker.glb"}`;
}

const rank = (tier: ModelTier) => MODEL_TIERS.indexOf(tier);
const lower = (a: ModelTier, b: ModelTier) => (rank(a) <= rank(b) ? a : b);

/* ----------------------------------------------------------------- GPU */

export type GpuClass = "software" | "low" | "mid" | "high" | "unknown";

/**
 * Classifies a WebGL renderer string. Patterns cover the common desktop and
 * mobile families; anything else (or a masked string) is "unknown".
 */
export function classifyGpu(
  renderer: string | null,
  software: boolean,
): GpuClass {
  if (software) return "software";
  if (!renderer) return "unknown";
  const r = renderer.toLowerCase();
  // Mobile / embedded families first (some contain vendor names used below).
  if (/tegra|mali|adreno|powervr|sgx|videocore/.test(r)) {
    if (/adreno[^0-9]*(7\d\d|8\d\d)|mali-g(7\d|6[1-9]|7\d\d)/.test(r))
      return "mid";
    return "low";
  }
  // Discrete and high-end.
  if (/geforce\s*mx/.test(r)) return "mid";
  if (/nvidia|geforce|quadro|rtx|gtx/.test(r)) return "high";
  if (/radeon[^,)]*\b(rx|pro|r9|vii)\b/.test(r)) return "high";
  if (/intel.*\barc\b/.test(r)) return "high";
  if (/apple m\d+\s*(pro|max|ultra)/.test(r)) return "high";
  // Modern integrated.
  if (
    /iris\s*\(?r?\)?\s*xe|iris plus|uhd graphics 7\d\d|apple m\d+|radeon(\(tm\))? graphics|radeon vega|vega \d+ graphics/.test(
      r,
    )
  )
    return "mid";
  // Older integrated.
  if (/intel|hd graphics|uhd graphics/.test(r)) return "low";
  return "unknown";
}

const GPU_TIER: Record<Exclude<GpuClass, "unknown">, ModelTier> = {
  software: "very-low",
  low: "low",
  mid: "medium",
  high: "high",
};

/* ------------------------------------------------------------- network */

export type NetworkClass = "slow" | "limited" | "good" | "unknown";

/** Subset of the Network Information API (Chromium browsers only). */
interface ConnectionInfo {
  effectiveType?: string;
  downlink?: number;
  saveData?: boolean;
}

/** One measured download (see `timedFetch`). */
export interface DownloadSample {
  bytes: number;
  seconds: number;
  /** Served from the HTTP cache: says nothing about the network. */
  cached: boolean;
}

/** Below this many bytes a download is dominated by latency, not bandwidth. */
const MIN_SAMPLE_BYTES = 50_000;

export function readConnection(): ConnectionInfo | null {
  const connection = (navigator as Navigator & { connection?: ConnectionInfo })
    .connection;
  return connection && typeof connection.effectiveType === "string"
    ? connection
    : null;
}

export function classifyNetwork(
  connection: ConnectionInfo | null,
  sample: DownloadSample | null,
): NetworkClass {
  if (connection) {
    if (connection.saveData) return "slow";
    if (
      connection.effectiveType === "slow-2g" ||
      connection.effectiveType === "2g"
    )
      return "slow";
    if (connection.effectiveType === "3g") return "limited";
    if (connection.effectiveType === "4g")
      return (connection.downlink ?? 10) < 2 ? "limited" : "good";
  }
  if (
    sample &&
    !sample.cached &&
    sample.bytes >= MIN_SAMPLE_BYTES &&
    sample.seconds > 0
  ) {
    const mbps = (sample.bytes * 8) / sample.seconds / 1e6;
    if (mbps < 1) return "slow";
    if (mbps < 5) return "limited";
    return "good";
  }
  return "unknown";
}

/** Largest tier the connection allows (by download size). */
const NETWORK_CAP: Record<NetworkClass, ModelTier> = {
  slow: "very-low",
  limited: "low",
  good: "high",
  // Unknown: conservative, never more than the original model.
  unknown: "medium",
};

/* -------------------------------------------------------------- choice */

export interface DetailDecision {
  tier: ModelTier;
  gpu: GpuClass;
  network: NetworkClass;
  /** Why this tier, for the dev console and the detail menu. */
  reason: string;
}

export function decideTier(
  gpu: GpuClass,
  network: NetworkClass,
  touch: boolean,
): DetailDecision {
  const fromGpu =
    gpu === "unknown" ? (touch ? "low" : "medium") : GPU_TIER[gpu];
  let tier = lower(fromGpu, NETWORK_CAP[network]);
  // Only ship what was generated.
  while (!AVAILABLE_TIERS.includes(tier) && rank(tier) > 0)
    tier = MODEL_TIERS[rank(tier) - 1];
  const reason =
    `gpu=${gpu}${gpu === "unknown" ? ` (default ${fromGpu}${touch ? ", touch device" : ""})` : ` -> ${fromGpu}`}; ` +
    `network=${network} (cap ${NETWORK_CAP[network]})`;
  return { tier, gpu, network, reason };
}

export function isTouchDevice(): boolean {
  return (
    window.matchMedia?.("(pointer: coarse)").matches === true &&
    navigator.maxTouchPoints > 0
  );
}

/**
 * Fetches a file and measures the download. Uses Resource Timing for the
 * transferred size and network time when the browser provides them.
 */
export async function timedFetch(
  url: string,
  signal?: AbortSignal,
): Promise<{ buffer: ArrayBuffer; sample: DownloadSample }> {
  const start = performance.now();
  const response = await fetch(url, { signal });
  if (!response.ok)
    throw new Error(`Request for ${url} failed (${response.status})`);
  const buffer = await response.arrayBuffer();
  const elapsed = (performance.now() - start) / 1000;
  const entries = performance.getEntriesByName(
    new URL(url, location.href).href,
  );
  const entry = entries[entries.length - 1] as
    | PerformanceResourceTiming
    | undefined;
  const transferred = entry?.transferSize ?? 0;
  const cached =
    entry !== undefined && transferred === 0 && entry.decodedBodySize > 0;
  const network =
    entry && entry.responseEnd > entry.requestStart && entry.requestStart > 0
      ? (entry.responseEnd - entry.requestStart) / 1000
      : elapsed;
  return {
    buffer,
    sample: {
      bytes: transferred > 0 ? transferred : buffer.byteLength,
      seconds: network,
      cached,
    },
  };
}
